<?php
declare(strict_types=1);use Acorn\SafetyHealthcheck\Assessment\{CompletionService,AssessmentRepository};
final class CompletionTest extends IntegrationTestCase{public function test_completion_separates_marketing_and_audit_consent_and_hashes_report_token():void{[$service,$token]=$this->assessed();$result=(new CompletionService)->complete($token,['first_name'=>'Ada','last_name'=>'Lovelace','company'=>'Analytical Ltd','email'=>'ada@example.test','audit_requested'=>false,'marketing_consent'=>false,'website'=>'']);$row=(new AssessmentRepository)->find($result['assessment_id']);self::assertSame(hash('sha256',$result['report_token']),$row['report_token_hash']);self::assertStringNotContainsString($result['report_token'],$row['report_token_hash']);$snapshot=json_decode($row['snapshot_json'],true);self::assertSame('1.0',$snapshot['content_version']);self::assertArrayHasKey('question_text',$snapshot['findings'][0]);self::assertStringNotContainsString('M01',$snapshot['findings'][0]['positive_text']);self::assertSame(count($snapshot['findings']),array_sum([$snapshot['summary']['priority_count'],$snapshot['summary']['review_count'],$snapshot['summary']['addressed_count']]));$this->expectException(RuntimeException::class);$service->saveAnswer($token,'M01_COMPETENT_PERSON','no');}}
